// Layout: fixed column widths
tblProps.AppendChild(new TableLayout
{
    Type = TableLayoutValues.Fixed
});

// Center the table on the page
tblProps.AppendChild(new TableJustification
{
    Val = TableRowAlignmentValues.Center
